    final String javaHome = SystemProperties.getJavaHome();
    final List<String> list = new ArrayList<>();
    // Starting in JRE 9, .class files are in the modules directory. Add them to the path. final Path modulesPath = Paths.get(javaHome).resolve("lib/modules");
