private Calendar parse(final Class<?> sourceType, final Class<?> targetType, final String value, final DateFormat format)  {
    logFormat("Parsing", format);
    format.setLenient(false);
    final ParsePosition pos = new ParsePosition(0);
    final Date parsedDate = format.parse(value, pos);
    // ignore the result (use the Calendar) final int errorIndex = pos.getErrorIndex();
    if (errorIndex >= 0 || pos.getIndex() != value.length() || parsedDate == null)
    {
        String msg = "Error converting '" + toString(sourceType) + "' to '" + toString(targetType) + "'";
        if (format instanceof SimpleDateFormat)
        {
            final SimpleDateFormat simpleFormat = (SimpleDateFormat) format;
            msg += String.format(" using pattern '%s', localized pattern '%s', errorIndex %,d, calendar type %s, this %s", simpleFormat.toPattern(), simpleFormat.toLocalizedPattern(), errorIndex, format.getCalendar().getClass().getSimpleName(), this);
        }
        if (log().isDebugEnabled())
        {
            log().debug(" " + msg);
        }
        throw new ConversionException(msg);
    }
    return format.getCalendar();
}
