private static String compilePattern(final String pattern)  {
    // Bug: BCEL-77 - Instructions are assumed to be english, to avoid odd Locale issues final String lower = StringUtils.toRootLowerCase(pattern);
    final StringBuilder buf = new StringBuilder();
    final int size = pattern.length();
    for (int i = 0;
    i < size;
    i++)
    {
        char ch = lower.charAt(i);
        if (Character.isLetterOrDigit(ch))
        {
            final StringBuilder name = new StringBuilder();
            while ((Character.isLetterOrDigit(ch) || ch == '_') && i < size)
            {
                name.append(ch);
                if (++i >= size)
                {
                    break;
                }
                ch = lower.charAt(i);
            }
            i--;
            buf.append(mapName(name.toString()));
        }
        else if (!Character.isWhitespace(ch))
        {
            buf.append(ch);
        }
    }
    return buf.toString();
}
