private void visitStackAccessor(final Instruction o)  {
    final int consume = o.consumeStack(cpg);
    // Stack values are always consumed first;
    then produced. if (consume > stack().slotsUsed())
    {
        constraintViolated(o, "Cannot consume " + consume + " stack slots: only " + stack().slotsUsed() + " slot(s) left on stack!\nStack:\n" + stack());
    }
    final int produce = o.produceStack(cpg) - o.consumeStack(cpg);
    // Stack values are always consumed first;
    then produced. if (produce + stack().slotsUsed() > stack().maxStack())
    {
        constraintViolated(o, "Cannot produce " + produce + " stack slots: only " + (stack().maxStack() - stack().slotsUsed()) + " free stack slot(s) left.\nStack:\n" + stack());
    }
}
