    Type shouldBe = t;
    if (shouldBe == Type.BOOLEAN || shouldBe == Type.BYTE || shouldBe == Type.CHAR || shouldBe == Type.SHORT)
    {
        shouldBe = Type.INT;
    }
    if (t instanceof ReferenceType)
    {
        if (value instanceof ReferenceType)
