        }
        else
        {
            constraintViolated(o, "The stack top type '" + value + "' is not of a reference type as expected.");
        }
    }
    else if (shouldBe != value)
    {
        constraintViolated(o, "The stack top type '" + value + "' is not of type '" + shouldBe + "' as expected.");
