            else if (DynaBean.class.isAssignableFrom(elementType))
            {
                elem = get(i);
            }
            else
            {
                elem = ((WrapDynaBean) get(i)).getInstance();
            }
            Array.set(array, i, elem);
        }
        return array;
    }
