    file.writeShort(fields.length);
    for (final Field field : fields)
    {
        field.dump(file);
    }
    file.writeShort(methods.length);
    for (final Method method : methods)
    {
        method.dump(file);
    }
    if (attributes != null)
    {
        file.writeShort(attributes.length);
        for (final Attribute attribute : attributes)
        {
            attribute.dump(file);
        }
    }
    else
    {
        file.writeShort(0);
    }
    file.flush();
}
