public int getSourceLine(final int pos)  {
    int l = 0;
    int r = lineNumberTable.length - 1;
    if (r < 0)
    {
        return -1;
    }
    int minIndex = -1;
    int min = -1;
    /* * Do a binary search since the array is ordered. */ do
    {
        final int i = l + r >>> 1;
        final int j = lineNumberTable[i].getStartPC();
        if (j == pos)
        {
            return lineNumberTable[i].getLineNumber();
        }
        if (pos < j)
        {
            r = i - 1;
        }
        else
        {
            l = i + 1;
        }
        /* * If exact match can't be found (which is the most common case) return the line number that corresponds to the greatest * index less than pos. */ if (j < pos && j > min)
        {
            min = j;
            minIndex = i;
        }
    }
    while (l <= r);
    /* * It's possible that we did not find any valid entry for the bytecode offset we were looking for. */ if (minIndex < 0)
    {
        return -1;
    }
    return lineNumberTable[minIndex].getLineNumber();
}
