    // Check the new element type, matches all the // other elements in the List if (elementType != null && !newElementType.equals(elementType))
    {
        throw new IllegalArgumentException("Element Type " + newElementType + " doesn't match other elements " + elementType);
    }
    return dynaBean;
}
