            "is_getter_or_setter": false,
            "code": "```java\npublic static int getMaxStack(final ConstantPoolGen cp, final InstructionList il, final CodeExceptionGen[] et)  {\n    final BranchStack branchTargets = new BranchStack();\n    /* * Initially, populate the branch stack with the exception handlers, because these aren't (necessarily) branched to * explicitly. in each case, the stack will have depth 1, containing the exception object. */ for (final CodeExceptionGen element : et)\n    {\n        final InstructionHandle handlerPc = element.getHandlerPC();\n        if (handlerPc != null)\n        {\n            branchTargets.push(handlerPc, 1);\n        }\n    }\n    int stackDepth = 0;\n    int maxStackDepth = 0;\n    InstructionHandle ih = il.getStart();\n    while (ih != null)\n    {\n        final Instruction instruction = ih.getInstruction();\n        final short opcode = instruction.getOpcode();\n        final int delta = instruction.produceStack(cp) - instruction.consumeStack(cp);\n        stackDepth += delta;\n        if (stackDepth > maxStackDepth)\n        {\n            maxStackDepth = stackDepth;\n        }\n        // choose the next instruction based on whether current is a branch. if (instruction instanceof BranchInstruction)\n        {\n            final BranchInstruction branch = (BranchInstruction) instruction;\n            if (instruction instanceof Select)\n            {\n                // explore all of the select's targets. the default target is handled below. final Select select = (Select) branch;\n                final InstructionHandle[] targets = select.getTargets();\n                for (final InstructionHandle target : targets)\n                {\n                    branchTargets.push(target, stackDepth);\n                }\n                // nothing to fall through to. ih = null;\n            }\n            else if (!(branch instanceof IfInstruction))\n            {\n                // if an instruction that comes back to following PC, // push next instruction, with stack depth reduced by 1. if (opcode == Const.JSR || opcode == Const.JSR_W)\n                {\n                    branchTargets.push(ih.getNext(), stackDepth - 1);\n                }\n                ih = null;\n            }\n            // for all branches, the target of the branch is pushed on the branch stack. // conditional branches have a fall through case, selects don't, and // jsr/jsr_w return to the next instruction. branchTargets.push(branch.getTarget(), stackDepth);\n        }\n        else // check for instructions that terminate the method. if (opcode == Const.ATHROW || opcode == Const.RET || opcode >= Const.IRETURN && opcode <= Const.RETURN)\n        {\n            ih = null;\n        }\n        // normal case, go to the next instruction. if (ih != null)\n        {\n            ih = ih.getNext();\n        }\n        // if we have no more instructions, see if there are any deferred branches to explore. if (ih == null)\n        {\n            final BranchTarget bt = branchTargets.pop();\n            if (bt != null)\n            {\n                ih = bt.target;\n                stackDepth = bt.stackDepth;\n            }\n        }\n    }\n    return maxStackDepth;\n}\n```"
