Annotations(rvaIndex, rvaData.length, new DataInputStream(new ByteArrayInputStream(rvaData)), cp.getConstantPool()));\n        }\n        if (riaData.length > 2)\n        {\n            newAttributes.add( new RuntimeInvisibleAnnotations(riaIndex, riaData.length, new DataInputStream(new ByteArrayInputStream(riaData)), cp.getConstantPool()));\n        }\n        return newAttributes.toArray(Attribute.EMPTY_ARRAY);\n    }\n    catch (final IOException e)\n    {\n        System.err.println(\"IOException whilst processing annotations\");\n        e.printStackTrace();\n    }\n    return null;\n}\n```"
