protected void adjustSize()  {
    // 3 extra spaces are needed as some entries may take 3 slots if (index + 3 >= Const.MAX_CP_ENTRIES + 1)
    {
        throw new IllegalStateException("The number of constants " + (index + 3) + " is over the size of the constant pool: " + Const.MAX_CP_ENTRIES);
    }
    if (index + 3 >= size)
    {
        final Constant[] tmp = constants;
        size *= 2;
        // the constant array shall not exceed the size of the constant pool size = Math.min(size, Const.MAX_CP_ENTRIES + 1);
        constants = new Constant[size];
        System.arraycopy(tmp, 0, constants, 0, index);
    }
}
