        final Converter<Float> floatConverter1 = new FloatConverter();
        // Emulate the container invoking a component #1, and the component // registering a custom converter instance whose class is // available via the "shared" classloader. Thread.currentThread().setContextClassLoader(componentLoader1);
        {
