    "is_getter_or_setter": false,
    "code": "```java
private void forceGarbageCollection(final WeakReference<?> target)  {
    int bytes = 2;
    while (target.get() != null)
    {
        System.gc();
        // Create increasingly-large amounts of non-referenced memory // in order to persuade the JVM to collect it. We are hoping // here that the JVM is dumb enough to run a full gc pass over // all data (including the target) rather than simply collecting // this easily-reclaimable memory! try
        {
            @SuppressWarnings("unused") final byte[] b = new byte[bytes];
            bytes *= 2;
        }
        catch (final OutOfMemoryError e)
        {
            // well that sure should have forced a garbage collection // run to occur! break;
        }
    }
    // and let's do one more just to clean up any garbage we might have // created on the last pass. System.gc();
}
