private void ensureExistingParameterAnnotationsUnpacked()  {
    if (haveUnpackedParameterAnnotations)
    {
        return;
    }
    // Find attributes that contain parameter annotation data final Attribute[] attrs = getAttributes();
    ParameterAnnotations paramAnnVisAttr = null;
    ParameterAnnotations paramAnnInvisAttr = null;
    for (final Attribute attribute : attrs)
    {
        if (attribute instanceof ParameterAnnotations)
        {
            // Initialize paramAnnotations if (!hasParameterAnnotations)
            {
                @SuppressWarnings("unchecked") // OK final List<AnnotationEntryGen>[] parmList = new List[argTypes.length];
                paramAnnotations = parmList;
                Arrays.setAll(paramAnnotations, i -> new ArrayList<>());
            }
            hasParameterAnnotations = true;
            final ParameterAnnotations rpa = (ParameterAnnotations) attribute;
            if (rpa instanceof RuntimeVisibleParameterAnnotations)
            {
                paramAnnVisAttr = rpa;
            }
            else
            {
                paramAnnInvisAttr = rpa;
            }
            final ParameterAnnotationEntry[] parameterAnnotationEntries = rpa.getParameterAnnotationEntries();
            for (int j = 0;
            j < parameterAnnotationEntries.length;
            j++)
            {
                // This returns Annotation[] ... final ParameterAnnotationEntry immutableArray = rpa.getParameterAnnotationEntries()[j];
                // ... which needs transforming into an AnnotationGen[] ... final List<AnnotationEntryGen> mutable = makeMutableVersion(immutableArray.getAnnotationEntries());
                // ... then add these to any we already know about paramAnnotations[j].addAll(mutable);
            }
        }
    }
    if (paramAnnVisAttr != null)
    {
        removeAttribute(paramAnnVisAttr);
    }
    if (paramAnnInvisAttr != null)
    {
        removeAttribute(paramAnnInvisAttr);
    }
    haveUnpackedParameterAnnotations = true;
}
