    final String className = "org.apache.commons.beanutils2.memoryleaktests.pojotests.SomeMappedPojo";
    // The classLoader will go away only when these following variables are released ClassLoader loader = newClassLoader();
    Class<?> beanClass = loader.loadClass(className);
    Object bean = beanClass.newInstance();
    final WeakReference<ClassLoader> someRef = new WeakReference<>(loader);
    // Sanity checks only assertNotNull(loader, "ClassLoader is null");
    assertNotNull(beanClass, "BeanClass is null");
    assertNotSame(getClass().getClassLoader(), beanClass.getClassLoader(), "ClassLoaders should be different..");
    assertSame(beanClass.getClassLoader(), loader, "BeanClass ClassLoader incorrect");
    // if you comment the following three lines, the test will work, and the ClassLoader will be released. // That proves that nothing is wrong with the test, and PropertyUtils is holding a reference assertEquals("Second Value", PropertyUtils.getProperty(bean, "mappedProperty(Second Key)"));
    PropertyUtils.setProperty(bean, "mappedProperty(Second Key)", "New Second Value");
    assertEquals("New Second Value", PropertyUtils.getProperty(bean, "mappedProperty(Second Key)"));
    // this should make the reference go away. loader = null;
    beanClass = null;
    bean = null;
    // PropertyUtilsBean uses the MethodUtils's method cache for mapped properties. // Uncomment the following line to check this is not just a repeat of that memory leak. // MethodUtils.clearCache();
