    {
        // sanity check;
        who's paranoid?? :-) assertEquals(origContextClassLoader, ConvertUtils.class.getClassLoader());
        // create a custom classloader for a "component" // just like a container would. ClassReloader componentLoader = new ClassReloader(origContextClassLoader);
        // Load a custom Converter via component loader. This emulates what // would happen if a user wrote their own FloatConverter subclass // and deployed it via the component-specific classpath. Thread.currentThread().setContextClassLoader(componentLoader);
        {
            // Here we pretend we're running inside the component, and that // a class FloatConverter has been loaded from the component's // private classpath. final Class<?> newFloatConverterClass = componentLoader.reload(FloatConverter.class);
            Object newFloatConverter = newFloatConverterClass.newInstance();
            assertSame(newFloatConverter.getClass().getClassLoader(), componentLoader);
            // verify that this new object does implement the Converter type // despite being loaded via a classloader different from the one // that loaded the Converter class. assertInstanceOf(Converter.class, newFloatConverter, "Converter loader via child does not implement parent type");
            // this converter registration will only apply to the // componentLoader classloader... ConvertUtils.register((Converter) newFloatConverter, Float.TYPE);
            // After registering a custom converter, lookup should return // it back to us. We'll try this lookup again with a different // context-classloader set, and shouldn't see it final Converter<Float> componentConverter = ConvertUtils.lookup(Float.TYPE);
            assertSame(componentConverter.getClass().getClassLoader(), componentLoader);
            newFloatConverter = null;
        }
        Thread.currentThread().setContextClassLoader(origContextClassLoader);
        // Because the context classloader has been reset, we shouldn't // see the custom registered converter here... final Converter<Float> sharedConverter = ConvertUtils.lookup(Float.TYPE);
        assertFalse(sharedConverter.getClass().getClassLoader() == componentLoader);
        // and here we should see it again Thread.currentThread().setContextClassLoader(componentLoader);
        {
            final Converter<Float> componentConverter = ConvertUtils.lookup(Float.TYPE);
            assertSame(componentConverter.getClass().getClassLoader(), componentLoader);
