    // Fill up memory final SoftReference<Object> ref = new SoftReference<>(new Object());
    int count = 0;
    while (ref.get() != null && count++ < 5)
    {
        java.util.ArrayList<String> list = new java.util.ArrayList<>();
        try
        {
            long i = 0;
            while (ref.get() != null)
            {
                list.add( "A Big String A Big String A Big String A Big String A Big String A Big String A Big String A Big String A Big String A Big String " + i++);
            }
            System.out.println("Count(1) " + count + " : " + getMemoryStats());
        }
        catch (final OutOfMemoryError ignored)
        {
            // Cannot do anything here
        }
        // Trying to debug Continuum test fail: try calling GC before releasing the memory System.gc();
        list.clear();
        list = null;
        System.gc();
        System.out.println("After GC2: " + getMemoryStats() + " Count " + count);
        Thread.sleep(1000);
    }
    final boolean isNotNull = ref.get() != null;
    System.out.println("Count " + count + " " + isNotNull);
    // debug for Continuum failure final String message = "Your JVM is not releasing SoftReference, try running the test with less memory (-Xmx)";
    assumeFalse(isNotNull, message);
}
