public void setProperty(final Object bean, String name, final Object value) throws IllegalAccessException, InvocationTargetException  {
    // Trace logging (if enabled) if (LOG.isTraceEnabled())
    {
        final StringBuilder sb = new StringBuilder(" setProperty(");
        sb.append(bean);
        sb.append(", ");
        sb.append(name);
        sb.append(", ");
        if (value == null)
        {
            sb.append("<NULL>");
        }
        else if (value instanceof String)
        {
            sb.append((String) value);
        }
        else if (value instanceof String[])
        {
            final String[] values = (String[]) value;
            sb.append('[');
            for (int i = 0;
            i < values.length;
            i++)
            {
                if (i > 0)
                {
                    sb.append(',');
                }
                sb.append(values[i]);
            }
            sb.append(']');
        }
        else
        {
            sb.append(value.toString());
        }
        sb.append(')');
        LOG.trace(sb.toString());
    }
    // Resolve any nested expression to get the actual target bean Object target = bean;
    final Resolver resolver = getPropertyUtils().getResolver();
    while (resolver.hasNested(name))
    {
        try
        {
            target = getPropertyUtils().getProperty(target, resolver.next(name));
