        {
            throw new NoSuchMethodException("Unknown property '" + name + "' on bean class '" + bean.getClass() + "'");
        }
        ((DynaBean) bean).set(name, index, value);
        return;
    }
    // Retrieve the property descriptor for the specified property final PropertyDescriptor descriptor = getPropertyDescriptor(bean, name);
    if (descriptor == null)
    {
        throw new NoSuchMethodException("Unknown property '" + name + "' on bean class '" + bean.getClass() + "'");
    }
    // Call the indexed setter method if there is one if (descriptor instanceof IndexedPropertyDescriptor)
    {
        Method writeMethod = ((IndexedPropertyDescriptor) descriptor).getIndexedWriteMethod();
        writeMethod = getAccessibleMethod(bean, writeMethod);
