    // Clear BeanUtilsBean's PropertyUtilsBean descriptor caches BeanUtilsBean.getInstance().getPropertyUtils().clearDescriptors();
    // Clear LocaleBeanUtilsBean's PropertyUtilsBean descriptor caches LocaleBeanUtilsBean.getLocaleBeanUtilsInstance().getPropertyUtils().clearDescriptors();
