            }
            System.out.println("Count(1) " + count + " : " + getMemoryStats());
        }
        catch (final OutOfMemoryError ignored)
        {
            // Cannot do anything here
        }
        // Trying to debug Continuum test fail: try calling GC before releasing the memory System.gc();
        list.clear();
        list = null;
